// Executes the actual checkout controller; synthetic requests only.
import test from 'node:test';import assert from 'node:assert/strict';import vm from 'node:vm';import {readFileSync} from 'node:fs';import {safeText} from '../web/model.js';
const source=readFileSync(new URL('../web/app.js',import.meta.url),'utf8');
const controller=source.slice(source.indexOf('let checkoutGeneration='),source.indexOf('let fileOpGeneration='));
function harness(){
 const elements=new Map(),calls=[],timers=[],state={mode:'select',busy:false,workspaceId:null};
 const config={enabled:true,state:'ready',url:'https://svn.example/<repo>',destination:'/local/<new>'};
 const plan={...config,planToken:'token',expiresIn:120,ignoreExternals:true,remoteAccess:false};
 const result={...config,verified:true,workspaceId:'new',ignoreExternals:true};
 function $(id){if(!elements.has(id))elements.set(id,{open:false,disabled:true,textContent:'',innerHTML:'',classList:{add(){},remove(){}}});return elements.get(id);}
 let response=async path=>path.endsWith('preflight')?plan:path.endsWith('apply')?result:config;
 const context=vm.createContext({state,$,standalone:false,Date,esc:safeText,modalView:'',setTimeout:fn=>timers.push(fn),log(){},setBusy:b=>state.busy=b,modal:(title,content)=>{vm.runInContext('invalidateCheckout()',context);context.modalView='generic';$('modal').open=true;$('modal-content').innerHTML=content;},api:async(path,body)=>{calls.push([path,body]);return response(path,body);}});
 vm.runInContext(controller,context);const run=s=>vm.runInContext(s,context);
 return {context,state,$,calls,timers,config,plan,result,run,respond:fn=>response=fn,close:()=>{$('modal').open=false;context.modalView='';run('invalidateCheckout()');}};
}
test('select mode opens only local config; fixed escaped targets; explicit preflight and single confirmation',async()=>{const h=harness();await h.run('openCheckout()');assert.deepEqual(h.calls.map(x=>x[0]),['/api/checkout']);assert.match(h.$('modal-content').innerHTML,/&lt;repo&gt;/);assert.doesNotMatch(h.$('modal-content').innerHTML,/<input/);await h.run('preflightCheckout()');assert.equal(h.$('checkout-confirm').disabled,false);await h.run('applyCheckout()');await h.run('applyCheckout()');assert.equal(h.calls.filter(x=>x[0].endsWith('apply')).length,1);assert.equal(h.state.workspaceId,null);assert.match(h.$('checkout-last-result').textContent,/已核实/);assert.deepEqual(JSON.parse(JSON.stringify(h.calls[2][1])),{planToken:'token',confirmed:true});});
test('demo and standalone never issue checkout requests',async()=>{for(const flag of ['demo','standalone']){const h=harness();if(flag==='demo')h.state.mode='demo';else h.context.standalone=true;await h.run('openCheckout()');await h.run('preflightCheckout()');assert.equal(h.calls.length,0);}});
test('disabled config offers no preflight; malformed plans cannot confirm',async()=>{const h=harness();h.respond(()=>({enabled:false}));await h.run('openCheckout()');await h.run('preflightCheckout()');assert.equal(h.calls.length,1);for(const edit of [p=>p.url='other',p=>p.remoteAccess=true,p=>p.ignoreExternals=false,p=>p.expiresIn=999,p=>p.planToken='']){const x=harness();await x.run('openCheckout()');edit(x.plan);await x.run('preflightCheckout()');await x.run('applyCheckout()');assert.equal(x.calls.length,2);}});
test('expiry and dismissal invalidate plan',async()=>{for(const close of [false,true]){const h=harness();await h.run('openCheckout()');await h.run('preflightCheckout()');if(close)h.close();else h.timers[0]();await h.run('applyCheckout()');assert.equal(h.calls.length,2);assert.equal(h.$('checkout-confirm').disabled,true);}});
test('late config/preflight never repopulates dismissed/replaced modal',async()=>{for(const preflight of [false,true]){const h=harness();if(preflight)await h.run('openCheckout()');let resolve;h.respond(()=>new Promise(r=>resolve=r));const pending=h.run(preflight?'preflightCheckout()':'openCheckout()');h.close();h.$('modal-content').innerHTML='replacement';resolve(preflight?h.plan:h.config);await pending;assert.equal(h.$('modal-content').innerHTML,'replacement');assert.equal(h.$('checkout-confirm').disabled,true);}});
test('double preflight and double apply excluded, late success persists without reopening',async()=>{const h=harness();await h.run('openCheckout()');let resolve;h.respond(()=>new Promise(r=>resolve=r));const pre=h.run('preflightCheckout()');await h.run('preflightCheckout()');resolve(h.plan);await pre;const apply=h.run('applyCheckout()');await h.run('applyCheckout()');h.close();resolve(h.result);await apply;assert.equal(h.calls.length,3);assert.equal(h.$('modal').open,false);assert.match(h.$('checkout-last-result').textContent,/已核实/);assert.equal(h.state.workspaceId,null);});
test('network, 503 and malformed apply outcomes are uncertain and never retried on reopen',async()=>{for(const status of [0,503,'malformed']){const h=harness();await h.run('openCheckout()');await h.run('preflightCheckout()');h.respond(()=>{if(status==='malformed')return {};throw Object.assign(Error('failed'),{httpStatus:status});});await h.run('applyCheckout()');assert.match(h.$('checkout-last-result').textContent,/结果未知/);h.close();h.respond(()=>h.config);await h.run('openCheckout()');await h.run('preflightCheckout()');await h.run('applyCheckout()');assert.equal(h.calls.filter(x=>x[0].endsWith('apply')).length,1);}});
test('server session outcome restored after reload without reapply',async()=>{for(const state of ['completed','uncertain']){const h=harness();h.config.state=state;h.config.result=h.result;await h.run('openCheckout()');await h.run('preflightCheckout()');await h.run('applyCheckout()');assert.equal(h.calls.length,1);assert.match(h.$('checkout-last-result').textContent,state==='completed'?/已核实/:/结果未知/);}});
test('4xx rejection retains attempt latch even if explicit reopen returns ready',async()=>{const h=harness();await h.run('openCheckout()');await h.run('preflightCheckout()');h.respond(()=>{throw Object.assign(Error('rejected'),{httpStatus:409});});await h.run('applyCheckout()');assert.match(h.$('checkout-last-result').textContent,/本会话可能已有检出/);assert.doesNotMatch(h.$('checkout-last-result').textContent,/未开始检出/);h.close();h.respond(()=>h.config);await h.run('openCheckout()');await h.run('preflightCheckout()');await h.run('applyCheckout()');assert.equal(h.calls.filter(x=>x[0].endsWith('apply')).length,1);assert.equal(h.$('checkout-preflight').disabled,true);});
test('explicit reopen after rejected apply can restore server verified completion',async()=>{const h=harness();await h.run('openCheckout()');await h.run('preflightCheckout()');h.respond(()=>{throw Object.assign(Error('rejected'),{httpStatus:409});});await h.run('applyCheckout()');h.close();h.config.state='completed';h.config.result=h.result;h.respond(()=>h.config);await h.run('openCheckout()');assert.match(h.$('checkout-last-result').textContent,/已核实/);assert.equal(h.$('checkout-preflight').disabled,true);assert.equal(h.calls.filter(x=>x[0].endsWith('apply')).length,1);});
test('actual modal lifecycle and toolbar handlers are wired',()=>{for(const marker of ['function modal(title,content)',"$('modal').addEventListener('cancel'","$('modal').addEventListener('close'"]){assert.match(source.split('\n').find(l=>l.startsWith(marker)),/invalidateCheckout\(\)/);}assert.match(source,/\$\('open-checkout'\).onclick=openCheckout/);});

test('checkout review discloses execution-time HEAD and no selected revision',()=>{assert.match(source,/仅检出执行时 HEAD，不支持指定修订/);assert.match(source,/本地预检不固定远程版本/);});
